action.command:
cd /workspace && python3 - <<'EOF'
import os,re
# check html pages for referenced relative assets
bad=[]
for root,dirs,files in os.walk('.'):
    if '.git' in root: continue
    for f in files:
        if f.endswith('.html'):
            p=os.path.join(root,f)
            txt=open(p,encoding='utf-8',errors='replace').read()
            for m in re.finditer(r'(?:src|href)\s*=\s*"([^"]+)"',txt):
                u=m.group(1)
                if u.startswith(('http://','https://','//','#','data:')): continue
                c=os.path.normpath(os.path.join(root,u.split('?')[0].split('#')[0]))
                if not os.path.exists(c):
                    bad.append((p,u))
print("missing html refs:",len(bad))
for x in bad[:60]: print(x)
EOF

